package dk.stream.android;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.TimeUnit;
import okhttp3.*;
import okhttp3.mockwebserver.*;
import org.junit.*;
import static org.junit.Assert.*;

public class WebDavClientTest {
 private MockWebServer server;private WebDavClient client;
 @Before public void setup() throws Exception {server=new MockWebServer();server.start();client=new WebDavClient(server.url("/"),"person@example.com","test-secret");}
 @After public void close() throws Exception {client.cancel();server.shutdown();}
 private static String entry(String href,String name,String mime,boolean folder,long size,String status){return "<d:response><d:href>"+href.replace("&","&amp;")+"</d:href><d:propstat><d:prop><d:displayname>"+name.replace("&","&amp;")+"</d:displayname><d:resourcetype>"+(folder?"<d:collection/>":"")+"</d:resourcetype><d:getcontenttype>"+mime+"</d:getcontenttype><d:getcontentlength>"+size+"</d:getcontentlength></d:prop><d:status>HTTP/1.1 "+status+"</d:status></d:propstat></d:response>";}
 private void listing(String entries){server.enqueue(new MockResponse().setResponseCode(207).setHeader("Content-Type","application/xml").setBody("<?xml version=\"1.0\"?><d:multistatus xmlns:d=\"DAV:\">"+entries+"</d:multistatus>"));}
 private String read(InputStream stream) throws Exception {try(InputStream input=stream;ByteArrayOutputStream output=new ByteArrayOutputStream()){byte[] buffer=new byte[256];int n;while((n=input.read(buffer))!=-1)output.write(buffer,0,n);return output.toString("UTF-8");}}
 @Test public void browsingUsesDepthOneAndNeverOpensMediaBytes() throws Exception {listing(entry("/","Root","",true,0,"200 OK")+entry("/folder/","Folder","",true,0,"200 OK")+entry("/song.mp3","Song.mp3","audio/mpeg",false,123,"200 OK")+entry("/film.mkv","Film.mkv","application/octet-stream",false,456,"200 OK")+entry("/notes.pdf","Notes.pdf","application/pdf",false,1,"200 OK"));List<WebDavClient.Entry> entries=client.list(server.url("/"));assertEquals(3,entries.size());assertTrue(entries.get(0).folder);assertEquals("Film.mkv",entries.get(1).name);assertEquals(456,entries.get(1).size);RecordedRequest request=server.takeRequest();assertEquals("PROPFIND",request.getMethod());assertEquals("1",request.getHeader("Depth"));assertEquals(Credentials.basic("person@example.com","test-secret",StandardCharsets.UTF_8),request.getHeader("Authorization"));assertEquals(1,server.getRequestCount());}
 @Test public void ignoresForeignLinksParentFoldersDeepEntriesAndFailedProperties() throws Exception {listing(entry("/Music/","Music","",true,0,"200 OK")+entry("/outside.mp3","Outside.mp3","audio/mpeg",false,1,"200 OK")+entry("https://evil.example/song.mp3","Foreign.mp3","audio/mpeg",false,1,"200 OK")+entry("/Music/deep/hidden.mp3","Hidden.mp3","audio/mpeg",false,1,"200 OK")+entry("/Music/denied.mp3","Denied.mp3","audio/mpeg",false,1,"404 Not Found")+entry("/Music/ok.mp3","OK.mp3","audio/mpeg",false,1,"200 OK"));List<WebDavClient.Entry> entries=client.list(server.url("/Music/"));assertEquals(1,entries.size());assertEquals("OK.mp3",entries.get(0).name);}
 @Test public void decodesUtf8AndXmlEntitiesWithoutCorruptingActualRequestPath() throws Exception {listing(entry("/S%C3%B8ndag%20%26%20venner.mp3","Søndag & venner.mp3","audio/mpeg",false,100,"200 OK"));WebDavClient.Entry entry=client.list(server.url("/")).get(0);assertEquals("Søndag & venner.mp3",entry.name);assertEquals("/S%C3%B8ndag%20%26%20venner.mp3",entry.url.encodedPath());}
 @Test public void directoryWithoutTrailingSlashStillResolvesItsChildren() throws Exception {listing(entry("song.mp3","Song.mp3","audio/mpeg",false,1,"200 OK"));List<WebDavClient.Entry> entries=client.list(server.url("/Music"));assertEquals("/Music/song.mp3",entries.get(0).url.encodedPath());assertEquals("/Music/",server.takeRequest().getPath());}
 @Test public void authenticationErrorsAreActionableAndNeverContainPassword() throws Exception {server.enqueue(new MockResponse().setResponseCode(401));try{client.list(server.url("/"));fail();}catch(IOException error){assertTrue(error.getMessage().contains("2FA"));assertFalse(error.getMessage().contains("test-secret"));assertFalse(error.getMessage().contains("person@example.com"));}}
 @Test public void sameOriginListingRedirectKeepsPropfindAndDepth() throws Exception {server.enqueue(new MockResponse().setResponseCode(301).setHeader("Location","/Music/"));listing(entry("/Music/a.mp3","A.mp3","audio/mpeg",false,1,"200 OK"));assertEquals(1,client.list(server.url("/")).size());server.takeRequest();RecordedRequest second=server.takeRequest();assertEquals("PROPFIND",second.getMethod());assertEquals("1",second.getHeader("Depth"));assertNotNull(second.getHeader("Authorization"));}
 @Test public void crossOriginListingRedirectIsNotFollowed() throws Exception {try(MockWebServer foreign=new MockWebServer()){foreign.start();server.enqueue(new MockResponse().setResponseCode(302).setHeader("Location",foreign.url("/").toString()));try{client.list(server.url("/"));fail();}catch(IOException expected){}assertEquals(0,foreign.getRequestCount());}}
 @Test public void streamedGetUsesRangeForSeeking() throws Exception {server.enqueue(new MockResponse().setResponseCode(206).setHeader("Content-Range","bytes 4-9/10").setBody("456789"));assertEquals("456789",read(client.open(server.url("/song.mp3"),4)));RecordedRequest request=server.takeRequest();assertEquals("GET",request.getMethod());assertEquals("bytes=4-",request.getHeader("Range"));assertNotNull(request.getHeader("Authorization"));}
 @Test public void credentialsAreRemovedBeforeAnyCdnRedirectRequest() throws Exception {try(MockWebServer cdn=new MockWebServer()){cdn.start();cdn.enqueue(new MockResponse().setBody("video"));server.enqueue(new MockResponse().setResponseCode(302).setHeader("Location",cdn.url("/file.mp4").toString()));assertEquals("video",read(client.open(server.url("/file.mp4"),0)));assertNull(cdn.takeRequest().getHeader("Authorization"));assertNotNull(server.takeRequest().getHeader("Authorization"));}}
 @Test public void serversThatIgnoreRangeAreStillReadFromRequestedPosition() throws Exception {server.enqueue(new MockResponse().setBody("0123456789"));assertEquals("789",read(client.open(server.url("/film.mp4"),7)));}
 @Test public void rejectsDtdWithoutOpeningAnExternalEntity() throws Exception {server.enqueue(new MockResponse().setResponseCode(207).setBody("<!DOCTYPE x [<!ENTITY steal SYSTEM 'file:///etc/passwd'>]><d:multistatus xmlns:d='DAV:'>"+entry("/a.mp3","&steal;","audio/mpeg",false,1,"200 OK")+"</d:multistatus>"));try{client.list(server.url("/"));fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("DTD"));}}
 @Test public void htmlLoginPageIsNotMistakenForAnEmptySuccessfulAccount() throws Exception {server.enqueue(new MockResponse().setBody("<html><body>Login</body></html>"));try{client.list(server.url("/"));fail();}catch(IOException expected){}}
 @Test public void entirelyDeniedMultistatusIsNotSuccessfulLogin() throws Exception {listing(entry("/","Root","",true,0,"403 Forbidden"));try{client.list(server.url("/"));fail();}catch(IOException expected){}}
 @Test public void duplicateResponsesDoNotDuplicateFiles() throws Exception {String item=entry("/song.mp3","Song.mp3","audio/mpeg",false,1,"200 OK");listing(item+item);assertEquals(1,client.list(server.url("/")).size());}
 @Test public void folderDownloadIncludesFilesHiddenFromMediaLists()throws Exception{String xml="<d:multistatus xmlns:d=\"DAV:\">"+entry("/folder/notes.txt","notes.txt","text/plain",false,8,"200 OK")+"</d:multistatus>";assertTrue(WebDavClient.parse(server.url("/folder/"),new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8))).isEmpty());List<WebDavClient.Entry> all=WebDavClient.parse(server.url("/folder/"),new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8)),true);assertEquals(1,all.size());assertEquals("notes.txt",all.get(0).name);}

 @Test public void cancelledStreamResumesFromWrittenBytesWithoutDuplicatingData()throws Exception{server.enqueue(new MockResponse().setBody("0123456789"));Call[] active={null};String first;try(InputStream input=client.open(server.url("/song.mp3"),0,call->active[0]=call)){byte[] prefix=new byte[4];new DataInputStream(input).readFully(prefix);first=new String(prefix,StandardCharsets.US_ASCII);assertNotNull(active[0]);active[0].cancel();}server.enqueue(new MockResponse().setResponseCode(206).setHeader("Content-Range","bytes 4-9/10").setBody("456789"));String resumed=read(client.open(server.url("/song.mp3"),4,call->active[0]=call));assertEquals("0123456789",first+resumed);server.takeRequest();assertEquals("bytes=4-",server.takeRequest().getHeader("Range"));}

}
